// Forward declaration of load_original_libgl() from glx_wrapper.c
extern void* original_libgl;
extern void load_original_libgl(void);

// Forward declarations of our custom implementations
extern void my_glEnable(GLenum cap);
extern void my_glDisable(GLenum cap);
extern GLboolean my_glIsEnabled(GLenum cap);

// Custom implementations for state tracking functions (don't forward to system)
void glEnable(GLenum cap) {
    my_glEnable(cap);
}

void glDisable(GLenum cap) {
    my_glDisable(cap);
}

GLboolean glIsEnabled(GLenum cap) {
    return my_glIsEnabled(cap);
}

